<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();Auth::requirePermission('companies.manage');$pdo=Database::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();try{$id=(int)($_POST['id']??0);$company=(int)($_POST['company_id']??0)?:null;$name=trim($_POST['name']??'');$city=(int)($_POST['city_id']??0)?:null;$status=in_array($_POST['status']??'active',['active','disabled'],true)?$_POST['status']:'active';if(mb_strlen($name)<2)throw new RuntimeException('اسم الفرع مطلوب.');if(($user['role']??'')==='company_manager')$company=(int)$user['company_id'];if($id){if(($user['role']??'')==='company_manager'){$chk=$pdo->prepare('SELECT COUNT(*) FROM branches WHERE id=? AND company_id=?');$chk->execute([$id,(int)$user['company_id']]);if(!(int)$chk->fetchColumn())throw new RuntimeException('لا تملك صلاحية تعديل هذا الفرع.');}$pdo->prepare('UPDATE branches SET company_id=?,name=?,city_id=?,address=?,phone=?,status=? WHERE id=?')->execute([$company,$name,$city,trim($_POST['address']??''),trim($_POST['phone']??''),$status,$id]);admin_log($pdo,$user,'branch.updated','branch',$id,'تعديل فرع');}else{$pdo->prepare('INSERT INTO branches(company_id,name,city_id,address,phone,status) VALUES(?,?,?,?,?,?)')->execute([$company,$name,$city,trim($_POST['address']??''),trim($_POST['phone']??''),$status]);admin_log($pdo,$user,'branch.created','branch',(int)$pdo->lastInsertId(),'إضافة فرع');}redirect('/admin/branches.php?saved=1');}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM branches WHERE id=?'.((($user['role']??'')==='company_manager')?' AND company_id=?':''));$q->execute(((($user['role']??'')==='company_manager')?[(int)$_GET['edit'],(int)$user['company_id']]:[(int)$_GET['edit']]));$edit=$q->fetch()?:null;}
$companies=$pdo->query('SELECT id,name FROM companies ORDER BY name')->fetchAll();$cities=$pdo->query('SELECT id,name_ar FROM cities WHERE is_active=1 ORDER BY name_ar')->fetchAll();$rows=$pdo->query('SELECT b.*,c.name company_name,ci.name_ar city_name FROM branches b LEFT JOIN companies c ON c.id=b.company_id LEFT JOIN cities ci ON ci.id=b.city_id ORDER BY b.id DESC')->fetchAll();admin_page_start('إدارة الفروع',$user);if($error)echo '<p class="notice danger">'.e($error).'</p>';if(isset($_GET['saved']))echo '<p class="notice">تم حفظ الفرع.</p>';if(($user['role']??'')==='company_manager')$companies=[array_filter($companies,fn($c)=>(int)$c['id']===(int)$user['company_id'])][0]??[];
echo '<section class="panel"><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(Security::csrf()).'"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><label>اسم الفرع<input name="name" required value="'.e($edit['name']??'').'"></label><label>الشركة<select name="company_id"><option value="">فرع مستقل</option>';foreach($companies as $c)echo '<option value="'.(int)$c['id'].'" '.((int)($edit['company_id']??0)===(int)$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select></label><label>المدينة<select name="city_id"><option value="">اختر المدينة</option>';foreach($cities as $c)echo '<option value="'.(int)$c['id'].'" '.((int)($edit['city_id']??0)===(int)$c['id']?'selected':'').'>'.e($c['name_ar']).'</option>';echo '</select></label><label>العنوان<input name="address" value="'.e($edit['address']??'').'"></label><label>الهاتف<input name="phone" value="'.e($edit['phone']??'').'"></label><label>الحالة<select name="status"><option value="active">نشط</option><option value="disabled">معطل</option></select></label><button class="btn btn-primary">حفظ الفرع</button></form></section><section class="panel"><table><thead><tr><th>الفرع</th><th>الشركة</th><th>المدينة</th><th>الهاتف</th><th>الحالة</th><th></th></tr></thead><tbody>';foreach($rows as $r){if(($user['role']??'')==='company_manager'&&(int)$r['company_id']!==(int)$user['company_id'])continue;echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['company_name']??'—').'</td><td>'.e($r['city_name']??'—').'</td><td>'.e($r['phone']).'</td><td>'.e($r['status']).'</td><td><a class="admin-link" href="/admin/branches.php?edit='.(int)$r['id'].'">تعديل</a></td></tr>';}echo '</tbody></table></section>';admin_page_end();
